import{_ as e,o,c as a,ah as r}from"./chunks/framework.BMM80GXQ.js";const i="/assets/2.0/images/settings/dark-theme.png",s="/assets/2.0/images/simple-product/simple.png",l="/assets/2.0/images/simple-product/datagrid.png",n="/assets/2.0/images/simple-product/product-edit-locale.png",c="/assets/2.0/images/simple-product/columns-selector.png",y=JSON.parse('{"title":"Simple Product","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/products/simple.md","filePath":"2.0/products/simple.md","lastUpdated":1775051911000}'),d={name:"2.0/products/simple.md"};function u(p,t,h,g,m,b){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="simple-product" tabindex="-1">Simple Product <a class="header-anchor" href="#simple-product" aria-label="Permalink to &quot;Simple Product&quot;">​</a></h1><h2 id="dark-light-theme" tabindex="-1">Dark / Light Theme <a class="header-anchor" href="#dark-light-theme" aria-label="Permalink to &quot;Dark / Light Theme&quot;">​</a></h2><p>UnoPim supports a <strong>Dark / Light Theme</strong> toggle. Click the sun/moon icon in the top-right corner of the header bar (next to the notification bell) to switch between light and dark mode. Your preference is saved and persists across sessions.</p><p><img src="'+i+'" alt="Dark Theme"></p><p>A simple product is the most basic and common product type. It&#39;s a physical, unique, standalone product without any other variations.</p><p>Simple products offer customizable options within a single SKU.</p><p>This is the step-by-step tutorial on how to add a simple product in <a href="https://unopim.com/" target="_blank" rel="noreferrer">UnoPim</a>.</p><h3 id="to-create-simple-product-in-unopim" tabindex="-1">To Create Simple Product in UnoPim <a class="header-anchor" href="#to-create-simple-product-in-unopim" aria-label="Permalink to &quot;To Create Simple Product in UnoPim&quot;">​</a></h3><ol><li>Click on <strong>Catalog &gt;&gt; Products &gt;&gt;</strong> select product type <strong>Simple</strong>,<strong>Family</strong> and enter <strong>SKU</strong>.</li></ol><p><img src="'+s+'" alt="Simple"></p><p>Now <strong>Save the Product</strong>, and you will get redirected to the Edit product page as shown below.</p><h3 id="general-attributes" tabindex="-1">General Attributes <a class="header-anchor" href="#general-attributes" aria-label="Permalink to &quot;General Attributes&quot;">​</a></h3><p>It displays the attributes assigned in the product&#39;s family grouped by attribute group.</p><p>The below given are required attributes present in the &quot;default&quot; family</p><ol><li><p>Enter <strong>SKU</strong> of the product</p></li><li><p>Enter <strong>Name</strong> of the product.</p></li><li><p>Now enter the <strong>URL Key</strong> of the product.</p></li></ol><h3 id="short-description" tabindex="-1">Short Description <a class="header-anchor" href="#short-description" aria-label="Permalink to &quot;Short Description&quot;">​</a></h3><p>Enter a short description of the features of the product.</p><h3 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h3><p>Mention your product in detail.</p><h3 id="price" tabindex="-1">Price <a class="header-anchor" href="#price" aria-label="Permalink to &quot;Price&quot;">​</a></h3><p>Insert the price and cost price of the product as shown in the below image</p><h3 id="technical" tabindex="-1">Technical <a class="header-anchor" href="#technical" aria-label="Permalink to &quot;Technical&quot;">​</a></h3><p>Now Enable the product from the status option as shown below.</p><h3 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h3><p>You can also assign the product into the root category as shown in the below image.</p><h3 id="associations" tabindex="-1">Associations <a class="header-anchor" href="#associations" aria-label="Permalink to &quot;Associations&quot;">​</a></h3><p>Also, you can add the Related Products, Upsell Products, and Cross Sell Products.</p><p><strong>1) Related Products -</strong> Related products are products that are similar to a selected product.</p><p>You can display potential substitutes help to them discover other similar products they might like.</p><p>To add Related Products click on Add in the Related Products section and search the product through the SKU which you want to add as a Related Product as shown in the image below.</p><p>Now click on <strong>Add Selected Product</strong> button.</p><p><strong>2) Up-Sell Products -</strong> Upselling is the practice of selling a higher-end version of an item they&#39;re interested in.</p><p>For instance, an electronics retailer pointing out the benefits of a better TV, a faster laptop, or a more durable tablet would be an example of upselling.</p><p>To add Up-Sell Products click on add in the Up-Sell Products section and search the product through the SKU which you want to add as a Up-Sell Product.</p><p>Now click on <strong>Add Selected Product</strong> button.</p><p><strong>3) Cross-Sell Products -</strong> Cross-sells are products that you promote, based on the current product. They are typically complementary items.</p><p>For example, if you are selling a laptop, cross-sells might be protective case stickers or a special adapter.</p><p>To add Cross-Sell Products click on add in the Cross-Sell Products section and search the product through SKU which you want to add as a Cross-Sell Product.</p><p>Now click on <strong>Add Selected Product</strong> button.</p><p>You can also add as many products as per your requirements.</p><p>At last, <strong>Save the Product</strong>.</p><p>Now the product is created successfully and it will be visible in <strong>Products Data Grid</strong> as shown in the below image.</p><p><img src="'+l+'" alt="Datagrid"></p><h2 id="product-completeness" tabindex="-1">Product Completeness <a class="header-anchor" href="#product-completeness" aria-label="Permalink to &quot;Product Completeness&quot;">​</a></h2><p>UnoPim v2.0 includes a <strong>Product Completeness</strong> system that provides quality scoring for your products. The completeness score indicates how much of the required product information has been filled in.</p><ul><li>Each channel has its own completeness calculation</li><li>Completeness is shown as a percentage (e.g., 89%)</li><li>Products with low completeness display the message &quot;Low completeness, add details to improve&quot;</li><li>Products that are nearly complete show &quot;Almost complete, just a few details left&quot;</li></ul><p>The completeness score is visible on the Dashboard and helps you identify products that need more information.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can use the completeness system together with the <strong>AI Auto-Enrichment</strong> feature to automatically fill in missing product fields and improve your completeness score.</p></div><h2 id="product-bulk-edit" tabindex="-1">Product Bulk Edit <a class="header-anchor" href="#product-bulk-edit" aria-label="Permalink to &quot;Product Bulk Edit&quot;">​</a></h2><p>UnoPim supports <strong>Bulk Edit</strong> capabilities that allow you to edit multiple products at once. This is especially useful when you need to update a common attribute across many products.</p><p>To use bulk edit:</p><ol><li>Navigate to <strong>Catalog &gt;&gt; Products</strong></li><li>Select the products you want to edit using the checkboxes</li><li>Click on the <strong>Bulk Actions</strong> dropdown</li><li>Select <strong>Edit</strong> and choose the attribute you want to update</li><li>Enter the new value and apply the changes</li></ol><h3 id="bulk-enable-disable-products" tabindex="-1">Bulk Enable / Disable Products <a class="header-anchor" href="#bulk-enable-disable-products" aria-label="Permalink to &quot;Bulk Enable / Disable Products&quot;">​</a></h3><ol><li>Select multiple products using the checkboxes</li><li>A bulk action bar appears at the top</li><li>Choose <strong>Enable</strong> or <strong>Disable</strong> to change the status of all selected products at once</li></ol><h3 id="bulk-delete-products" tabindex="-1">Bulk Delete Products <a class="header-anchor" href="#bulk-delete-products" aria-label="Permalink to &quot;Bulk Delete Products&quot;">​</a></h3><ol><li>Select the products you want to remove</li><li>Click the <strong>Delete</strong> bulk action</li><li>Confirm the deletion — this permanently removes the selected products</li></ol><h2 id="product-values-translation" tabindex="-1">Product Values Translation <a class="header-anchor" href="#product-values-translation" aria-label="Permalink to &quot;Product Values Translation&quot;">​</a></h2><p>The <strong>Product Values Translation</strong> feature allows you to translate product attribute values across all configured locales.</p><p><img src="'+n+'" alt="Product Edit with Locale Switcher"></p><h3 id="how-to-translate-product-values-manually" tabindex="-1">How to Translate Product Values Manually <a class="header-anchor" href="#how-to-translate-product-values-manually" aria-label="Permalink to &quot;How to Translate Product Values Manually&quot;">​</a></h3><ol><li>Navigate to <strong>Catalog &gt;&gt; Products</strong> and click <strong>Edit</strong> on the product you want to translate.</li><li>At the top of the edit page, you will see two dropdowns: <ul><li><strong>Channel Switcher</strong> (e.g., &quot;Default&quot;) — Select the channel whose values you want to edit.</li><li><strong>Locale Switcher</strong> (e.g., &quot;English (United States)&quot;) — Select the locale you want to enter translations for.</li></ul></li><li>Switch to the target locale (e.g., French, German, Hindi).</li><li>The form reloads with the attribute values for that locale. Fields that support per-locale values display a <strong>locale badge</strong> (e.g., <code>EN_US</code>).</li><li>Enter the translated values for each field (Name, Description, URL Key, etc.).</li><li>Click <strong>Save Product</strong> to store the translations.</li><li>Repeat for each locale you want to translate.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Attributes showing a <strong>DEFAULT</strong> badge are channel-specific. Attributes showing a locale badge (e.g., <strong>EN_US</strong>) are locale-specific. Attributes with both badges support values per channel AND per locale.</p></div><h3 id="auto-translation-with-magic-ai" tabindex="-1">Auto-Translation with Magic AI <a class="header-anchor" href="#auto-translation-with-magic-ai" aria-label="Permalink to &quot;Auto-Translation with Magic AI&quot;">​</a></h3><p>Instead of translating manually, you can enable <strong>Auto-Translation</strong> in <strong>Magic AI &gt;&gt; Settings &gt;&gt; Translation</strong>:</p><ol><li><strong>Enable</strong> the Translation toggle</li><li>Set the <strong>Source Channel</strong> and <strong>Source Locale</strong> (the language you write in, e.g., English)</li><li>Set the <strong>Target Channel</strong> and <strong>Target Locales</strong> (the languages to translate to)</li><li>Choose a <strong>Translation Model</strong> (you can pick a faster/cheaper provider for translations)</li><li>Optionally toggle <strong>Replace Existing Value</strong> to overwrite previous translations</li></ol><p>Once enabled, when you create or update a product, UnoPim automatically translates all locale-specific fields to the target locales using AI.</p><h2 id="dynamic-datagrid-columns-and-filters" tabindex="-1">Dynamic Datagrid Columns and Filters <a class="header-anchor" href="#dynamic-datagrid-columns-and-filters" aria-label="Permalink to &quot;Dynamic Datagrid Columns and Filters&quot;">​</a></h2><p>The Products Data Grid supports <strong>dynamic columns and filters</strong>. You can customize which columns are visible in your product listing and apply advanced filters to find specific products quickly.</p><h2 id="product-history" tabindex="-1">Product History <a class="header-anchor" href="#product-history" aria-label="Permalink to &quot;Product History&quot;">​</a></h2><p>You can view the product history by navigating to <strong>Catalog &gt;&gt; Products &gt;&gt; Edit Product</strong> and clicking on <strong>History</strong>.</p><p>Afterwards, in the <strong>Actions</strong> you can view the product history details.</p><h2 id="quick-export" tabindex="-1">Quick Export <a class="header-anchor" href="#quick-export" aria-label="Permalink to &quot;Quick Export&quot;">​</a></h2><p>You can quickly export your data in <strong>CSV, XLS, or XLSX</strong> formats directly from the product listing.</p><ol><li>Select the products you want to export</li><li>Click on the <strong>Quick Export</strong> button</li><li>Choose your preferred format</li><li>The export file will be downloaded</li></ol><h2 id="copy-product" tabindex="-1">Copy Product <a class="header-anchor" href="#copy-product" aria-label="Permalink to &quot;Copy Product&quot;">​</a></h2><p>You can quickly duplicate a product using the <strong>Copy</strong> action:</p><ol><li>Navigate to <strong>Catalog &gt;&gt; Products</strong></li><li>Find the product you want to copy in the datagrid</li><li>Click the <strong>Copy icon</strong> (clipboard icon) in the Actions column for that product</li><li>A new product is created as a duplicate with a new SKU</li><li>You can then edit the copied product to customize it</li></ol><h2 id="product-datagrid-columns" tabindex="-1">Product Datagrid Columns <a class="header-anchor" href="#product-datagrid-columns" aria-label="Permalink to &quot;Product Datagrid Columns&quot;">​</a></h2><p>The product datagrid supports <strong>dynamic column management</strong>. Click the <strong>Columns</strong> button above the datagrid to open the &quot;Manage columns&quot; modal.</p><p><img src="'+c+'" alt="Columns Selector"></p><p>The modal shows two panels:</p><ul><li><strong>Available Columns (left)</strong> — Lists all product attributes that can be added as columns (Parent, ID, Created At, Updated At, URL Key, Tax Category, Short Description, Description, Price, Cost, Meta Title, Meta Keywords, Meta Description, and all custom attributes). Paginated with search.</li><li><strong>Selected Columns (right)</strong> — Shows the currently visible columns. Default: SKU, Image, Name, Attribute Family, Status, Type, Complete.</li></ul><p>To customize:</p><ol><li>Drag columns from Available to Selected to add them</li><li>Drag columns within Selected to reorder them</li><li>Remove columns from Selected to hide them</li><li>Click <strong>Apply</strong> to save your column configuration</li></ol><h2 id="product-filters" tabindex="-1">Product Filters <a class="header-anchor" href="#product-filters" aria-label="Permalink to &quot;Product Filters&quot;">​</a></h2><p>Click the <strong>Filter</strong> button above the datagrid to expand the filter panel. You can filter products by:</p><ul><li>SKU, Name, Type (Simple/Configurable), Status (Enabled/Disabled), Attribute Family</li><li>Any visible column can be used as a filter</li><li>Filters support text search, dropdown selection, and date ranges</li><li>Multiple filters can be combined for precise results</li><li>Click <strong>Apply Filters</strong> to apply, or clear individual filters to reset</li></ul><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><p>UnoPim tracks a complete audit history for all major entities — not just products. Navigate to any entity&#39;s edit page and click on the <strong>History</strong> tab to view:</p><ul><li><strong>Products</strong> — Track all changes to product attributes, status, categories, associations</li><li><strong>Categories</strong> — View history of category name, description, and field changes</li><li><strong>Attributes</strong> — Track when attributes were created, modified, or configuration changed</li><li><strong>Attribute Families</strong> — View when attributes were added or removed from families</li><li><strong>Channels</strong> — Track channel configuration changes</li></ul><p>Each history entry shows: the date/time of the change, the user who made it, and the specific fields that were modified with before/after values. You can click the <strong>View</strong> action (eye icon) to see the full details of each change.</p><p><strong>Note:</strong> Attributes that support values per channel will display a channel badge, while attributes that support values per locale will display a locale badge. If an attribute supports both values per channel and values per locale, it will display both badges.</p>',92)])])}const w=e(d,[["render",u]]);export{y as __pageData,w as default};
